import { test } from "node:test";
import assert from "node:assert/strict";
import { PartitionLog } from "../src/log/partitionLog.ts";
import { BillingLedger, type Click } from "../src/billing/clicks.ts";
import { ClickConsumer } from "../src/billing/clickConsumer.ts";

const click = (n: number, advertiserId = "acme"): Click => ({ clickId: `clk-${n}`, campaignId: "black-friday", advertiserId, costMicros: 250_000 });

function streamOf(clicks: (Click | string)[]) {
    const log = new PartitionLog();
    for (const c of clicks) log.append(typeof c === "string" ? c : JSON.stringify(c));
    return log;
}

// Ledger whose database write fails the first time for the given click ids.
function flakyLedger(failOnce: string[]) {
    const ledger = new BillingLedger();
    const pending = new Set(failOnce);
    return {
        ledger,
        async upsertCharge(c: Click) {
            if (pending.delete(c.clickId)) throw new Error(`deadlock detected writing ${c.clickId}`);
            await ledger.upsertCharge(c);
        },
    };
}

test("every click in the stream is billed and the offset ends at the tail", async () => {
    const log = streamOf([1, 2, 3, 4, 5].map((n) => click(n)));
    const ledger = new BillingLedger();
    await new ClickConsumer(log, "billing", ledger, 2).catchUp();
    assert.equal(ledger.totalMicros("acme"), 1_250_000);
    assert.equal(await log.committed("billing"), 5);
});

test("replaying the stream from the start doesn't bill any click twice", async () => {
    const log = streamOf([1, 2, 3].map((n) => click(n)));
    const ledger = new BillingLedger();
    await new ClickConsumer(log, "billing", ledger).catchUp();
    await log.commit("billing", 0);
    await new ClickConsumer(log, "billing", ledger).catchUp();
    assert.equal(ledger.count(), 3);
    assert.equal(ledger.totalMicros("acme"), 750_000);
});

test("a click whose charge failed is billed on a later poll", async () => {
    const log = streamOf([1, 2, 3, 4].map((n) => click(n)));
    const store = flakyLedger(["clk-2"]);
    const consumer = new ClickConsumer(log, "billing", store, 10);
    const first = await consumer.pollOnce();
    assert.equal(first.failed, 1);
    console.log("committed offset after a batch where clk-2 failed:", await log.committed("billing"));
    await consumer.pollOnce();
    assert.equal(store.ledger.count(), 4);
});

test("the committed offset never moves past a click that wasn't billed", async () => {
    const log = streamOf([1, 2, 3, 4, 5, 6].map((n) => click(n)));
    const store = flakyLedger(["clk-4"]);
    const offsets: number[] = [];
    await new ClickConsumer(log, "billing", store, 10, (_, offset) => offsets.push(offset)).pollOnce();
    assert.deepEqual(offsets, [3]);
    assert.ok((await log.committed("billing")) <= 3, "offset 3 (clk-4) must still be ahead of the commit");
});

test("advertiser totals are complete after intermittent ledger errors", async () => {
    const clicks = Array.from({ length: 30 }, (_, i) => click(i, i % 3 === 0 ? "globex" : "acme"));
    const log = streamOf(clicks);
    const store = flakyLedger(["clk-0", "clk-7", "clk-8", "clk-21", "clk-29"]);
    await new ClickConsumer(log, "billing", store, 8).catchUp();
    assert.equal(store.ledger.totalMicros("globex"), 10 * 250_000);
    assert.equal(store.ledger.totalMicros("acme"), 20 * 250_000);
    assert.equal(await log.committed("billing"), 30);
});

test("malformed records are skipped without blocking the clicks behind them", async () => {
    const log = streamOf([click(1), "{garbage", JSON.stringify({ clickId: "clk-x" }), click(2)]);
    const ledger = new BillingLedger();
    const total = await new ClickConsumer(log, "billing", ledger).catchUp();
    assert.deepEqual(total, { billed: 2, invalid: 2, failed: 0 });
    assert.equal(await log.committed("billing"), 4);
});

test("a restarted consumer resumes from the group's committed offset", async () => {
    const log = streamOf([1, 2, 3, 4].map((n) => click(n)));
    const ledger = new BillingLedger();
    await new ClickConsumer(log, "billing", ledger, 2).pollOnce();
    log.append(JSON.stringify(click(5)));
    const resumed = await new ClickConsumer(log, "billing", ledger, 2).catchUp();
    assert.equal(resumed.billed, 3);
    assert.equal(ledger.count(), 5);
});
